function t9a_collect($p,$pipes){foreach($pipes as $h){if(is_resource($h))stream_set_blocking($h,false);}$o='';$e='';$d=microtime(true)+15;$running=true;while(microtime(true)<$d){$s=proc_get_status($p);$o.=is_resource($pipes[1])?stream_get_contents($pipes[1]):'';$e.=is_resource($pipes[2])?stream_get_contents($pipes[2]):'';$running=!empty($s['running']);if(!$running)break;usleep(20000);}if($running){proc_terminate($p);$end=microtime(true)+2;while(microtime(true)<$end){$s=proc_get_status($p);if(empty($s['running']))break;usleep(20000);}}foreach($pipes as $h){if(is_resource($h))fclose($h);}if(is_resource($p))proc_close($p);$r=json_decode(trim($o),true)?:['ok'=>false,'code'=>'WORKER_FAILED'];if(trim($e)!==''){$r['stderr']=trim($e);$r['ok']=false;$r['code']='WORKER_STDERR';}return $r;}
