function t9a_stop($p){if(!is_resource($p))return;$s=proc_get_status($p);if(!empty($s['running'])){proc_terminate($p);$end=microtime(true)+2;while(microtime(true)<$end){$s=proc_get_status($p);if(empty($s['running']))break;usleep(20000);}}proc_close($p);}
$pair=function($f,$x,$y,$tag)use($spawn){$tmp=sys_get_temp_dir().'/t9a-'.$tag.'-'.getmypid().'-'.bin2hex(random_bytes(3));mkdir($tmp,0777,true);$gate=$tmp.'/g';$owned=[];try{$a=$spawn($f['request_id'],$f['record_id'],$f['actor'],$x['reason'],$x['value'],$x['key'],$tmp.'/a',$gate,$owned);$b=$spawn($f['request_id'],$f['record_id'],$f['actor'],$y['reason'],$y['value'],$y['key'],$tmp.'/b',$gate,$owned);file_put_contents($gate,'x');return[t9a_collect($a[0],$a[1]),t9a_collect($b[0],$b[1])];}finally{if(is_file($gate))@unlink($gate);foreach($owned as $z){[$p,$pipes]=$z;t9a_stop($p);foreach($pipes as $h){if(is_resource($h))fclose($h);}}@rmdir($tmp);}};
