// Verify event identity and immutable finalization marker for the completed matrix.
$amendmentEvents = $db->where('event_type', 'clinical_record.amended')->get('request_events')->result();
foreach ($amendmentEvents as $event) {
    $meta = json_decode((string) $event->metadata_json, true);
    vcw_assert_true(strpos((string) $event->domain_event_key, 'clinical-amendment:') === 0, 'amendment event key');
    vcw_assert_true((int) $event->actor_user_id > 0 && is_array($meta) && !empty($meta['amendment_id']) && !empty($meta['record_id']) && (int) $meta['request_id'] === (int) $event->request_id, 'amendment event attribution');
